@router.post("/{order_id}/cancel")
@require_login
def cancel_order(request: Request, order_id: str) -> Response:
    current_user(request)

order = db.query_one("SELECT id, status FROM orders WHERE id = ?", (int(order_id),))
if order is None:
    raise HTTPError(404, "order not found")
if order["status"] == "cancelled":
    return Response(status=204)
reason = request.json().get("reason", "")
sql = f"UPDATE orders SET status = 'cancelled', cancel_reason = '{reason}' WHERE id = ?"
db.execute(sql, (int(order_id),))

